  applyTextWindowSettings(){const cssName=key=>key.replace(/[A-Z]/g,m=>`-${m.toLowerCase()}`);for(const element of document.querySelectorAll("[data-window]")){const mode=TEXT_WINDOW_CONFIG.modes[element.dataset.window],art=element.querySelector(".text-window-art");if(mode)for(const[key,value]of Object.entries(mode))element.style.setProperty(`--tw-${cssName(key)}`,value);const speaker=element.querySelector(".speaker-name"),text=element.querySelector("p");if(speaker)for(const[key,value]of Object.entries(TEXT_WINDOW_CONFIG.speaker))speaker.style.setProperty(cssName(key),value);if(text)for(const[key,value]of Object.entries(TEXT_WINDOW_CONFIG.text)){if(key==="fontSize"){element.style.fontSize=value;text.style.fontSize="inherit";}else text.style.setProperty(cssName(key),value);}if(art){art.hidden=!TEXT_WINDOW_CONFIG.imageSrc;art.style.backgroundImage=TEXT_WINDOW_CONFIG.imageSrc?`url("${TEXT_WINDOW_CONFIG.imageSrc}")`:"none";art.style.backgroundSize=TEXT_WINDOW_CONFIG.imageFit;}}}
