  showDialogueLine(){const line=this.dialogueLines[this.dialogueIndex],stage=this.currentScenarioStage();if(!line)return;if(this.dialogueMode==="still"){document.querySelector("#still-speaker").textContent=line.speaker??"";document.querySelector("#still-text").textContent=line.text??"";return;}const portrait=expressionLayer(stage.opponent,line.expression??"n",this.dialogueMode==="novel"?"novel":"battle");if(this.dialogueMode==="novel"){const bg=document.querySelector("#novel-background"),img=document.querySelector("#novel-portrait");bg.src=line.background??stage.background.src;bg.style.objectPosition=`${stage.novelBackgroundPosition.x}% ${stage.novelBackgroundPosition.y}%`;img.src=portrait.src;img.style.objectPosition=`${portrait.positionX}% ${portrait.positionY}%`;img.style.transform=`translate(${portrait.offsetX}%,${portrait.offsetY}%) scale(${portrait.scale})`;document.querySelector("#novel-speaker").textContent=line.speaker??"";document.querySelector("#novel-text").textContent=line.text??"";}else{this.applyCharacterLayer(document.querySelector("#character-portrait"),portrait);this.setMessage({speaker:line.speaker,text:line.text});}}
